INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, environment, enabled, created_by, source_type) VALUES ('ff.fin.p2305', 'Finance: accounts receivable, receipts, credit notes and collections (part 23.05)', 0, NULL, 0, 'migration', 'reference_seed');
