INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
  SELECT NULL, a.group_id, '170005', 'GST-TDS receivable (s.51 CGST Act)', 'GENERAL', 'DR', 'INR', 0, NULL, 0, 'migration', 'fin_p2305' FROM fin_accounts a WHERE a.company_id IS NULL AND a.code = '170004' AND a.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM fin_accounts x WHERE x.company_id IS NULL AND x.code = '170005');
INSERT INTO fin_accounts (company_id, group_id, code, name, account_type, normal_side, currency_code, is_control, control_kind, manual_posting_allowed, created_by, source_type)
